//! Which files an edit in the language server checks again, and which entry
//! points it queues, counted for each row of the reach table
//! `SymbolIndex::refresh` implements.
//!
//! The tree is generated by [`tree`]: one library under `lib/Framework/`, one
//! class a file, and [`PROGRAMS`] one-file programs that each autoload it. A
//! program's [role](role) says which part of the library it names, so the
//! files each edit can reach are known from the roles alone.
//!
//! Every file is its own entry point, and the first analysis to reach a file
//! owns it. The library sorts before the programs, and every class sorts after
//! the classes it extends or implements, so each library file is owned by its
//! own entry, and each program by itself. The entries an edit queues are
//! therefore exactly the files it reaches, the edited file left out. That file
//! is open, and its own analysis is the one check every edit costs.

use std::collections::BTreeSet;
use std::fs;
use std::path::PathBuf;

use nvs_diagnostics::canonical_key;
use nvs_lsp::{CheckScope, Documents, SymbolIndex, Work, uri_of};
use nvs_test::temp::TempDir;

/// The programs of the tree.
const PROGRAMS: usize = 200;

/// The roles the programs take in turn.
const ROLES: usize = 10;

/// A program that calls `Base::greet`.
const GREET: usize = 0;
/// A program that uses the enum `Status` and its cases.
const STATUS: usize = 1;
/// A program that decodes JSON into `Order`, whose `$total` is private.
const DECODE: usize = 2;
/// A program that calls `Page::size`, on a subclass of `Base`.
const PAGE: usize = 3;
/// A program that calls `Shape::area` on a `Square`.
const SHAPE: usize = 4;
/// A program that calls `Lone::value` and `Lone::twice`. Every role above
/// this one calls `Lone::value` alone.
const TWICE: usize = 5;

/// The library, one class a file, each after the classes it extends or
/// implements in path order. `Base` has a private, a protected and a public
/// method and a constant, `Page` extends it and `Post` extends `Page`.
/// `Square` and `Triangle` implement `Shape`. `Lone` has no subclass, and
/// `Order` is decoded from JSON.
const LIBRARY: [(&str, &str); 9] = [
    (
        "Base",
        "class Base\n{\n    public const int LIMIT = 3;\n\n    \
         private function secret(): int\n    {\n        return 1;\n    }\n\n    \
         protected function guard(): int\n    {\n        return $this->secret() + self::LIMIT;\n    }\n\n    \
         public function greet(): string\n    {\n        return 'hello';\n    }\n}\n",
    ),
    (
        "Lone",
        "class Lone\n{\n    private function hidden(): int\n    {\n        return 2;\n    }\n\n    \
         public function value(): int\n    {\n        return $this->hidden() + 1;\n    }\n\n    \
         public function twice(): int\n    {\n        return 4;\n    }\n}\n",
    ),
    (
        "Order",
        "#[Core\\Json\\Derive]\nclass Order\n{\n    public int $id;\n    \
         private int $total;\n\n    \
         public function constructor(int $id, int $total)\n    {\n        \
         $this->id = $id;\n        $this->total = $total;\n    }\n}\n",
    ),
    (
        "Page",
        "class Page extends Base\n{\n    public function size(): int\n    {\n        \
         return $this->guard() + 1;\n    }\n}\n",
    ),
    (
        "Post",
        "class Post extends Page\n{\n    public function words(): int\n    {\n        \
         return $this->size() * 2;\n    }\n}\n",
    ),
    (
        "Shape",
        "interface Shape\n{\n    public function area(): int;\n}\n",
    ),
    (
        "Square",
        "class Square implements Shape\n{\n    public function area(): int\n    {\n        \
         return 4;\n    }\n}\n",
    ),
    (
        "Status",
        "enum Status: int\n{\n    Draft = 1,\n    Live = 2,\n}\n",
    ),
    (
        "Triangle",
        "class Triangle implements Shape\n{\n    public function area(): int\n    {\n        \
         return 3;\n    }\n}\n",
    ),
];

/// The role of program `p`.
const fn role(p: usize) -> usize {
    p % ROLES
}

/// The path of program `p`, relative to the root.
fn program(p: usize) -> String {
    format!("p{p:03}.nvs")
}

/// The path of library class `class`, relative to the root.
fn class(class: &str) -> String {
    format!("lib/Framework/{class}.nvs")
}

/// The text of a program that autoloads the library and runs `body`.
fn program_text(body: &str) -> String {
    format!("<?nvs\nautoload 'Framework' from './lib/Framework';\n\n{body}")
}

/// What a program of `role` runs.
fn body(role: usize) -> &'static str {
    match role {
        GREET => {
            "use Framework\\Base;\n\nBase $base = new Base();\necho $base->greet(), \"\\n\";\n"
        }
        STATUS => {
            "use Framework\\Status;\n\nStatus $status = Status::Draft;\n\
             echo $status == Status::Live ? 'live' : 'draft', \"\\n\";\n"
        }
        DECODE => {
            "use Framework\\Order;\n\n\
             Order $order = Core\\Json::decodeAs<Order>('{\"id\": 7, \"total\": 9}');\n\
             echo $order->id, \"\\n\";\n"
        }
        PAGE => "use Framework\\Page;\n\nPage $page = new Page();\necho $page->size(), \"\\n\";\n",
        SHAPE => {
            "use Framework\\Shape;\nuse Framework\\Square;\n\n\
             Shape $shape = new Square();\necho $shape->area(), \"\\n\";\n"
        }
        TWICE => {
            "use Framework\\Lone;\n\nLone $lone = new Lone();\n\
             echo $lone->value() + $lone->twice(), \"\\n\";\n"
        }
        _ => "use Framework\\Lone;\n\nLone $lone = new Lone();\necho $lone->value(), \"\\n\";\n",
    }
}

/// Writes the library and [`PROGRAMS`] programs under a scratch directory
/// named after `name`.
fn tree(name: &str) -> TempDir {
    let dir = TempDir::new(nvs_repo::scratch(&format!("lsp-reach-{name}")));
    for (name, text) in LIBRARY {
        dir.write(
            &class(name),
            &format!("<?nvs\nnamespace Framework;\n\n{text}"),
        );
    }
    for p in 0..PROGRAMS {
        dir.write(&program(p), &program_text(body(role(p))));
    }
    dir
}

/// The index key of `relative` under `dir`.
fn key(dir: &TempDir, relative: &str) -> PathBuf {
    canonical_key(&dir.at(relative))
}

/// The programs whose role is one of `roles`.
fn programs(dir: &TempDir, roles: &[usize]) -> BTreeSet<PathBuf> {
    (0..PROGRAMS)
        .filter(|p| roles.contains(&role(*p)))
        .map(|p| key(dir, &program(p)))
        .collect()
}

/// The library files of `classes`.
fn library(dir: &TempDir, classes: &[&str]) -> BTreeSet<PathBuf> {
    classes.iter().map(|name| key(dir, &class(name))).collect()
}

/// Builds and settles the index of `dir`, opens library class `name`, and
/// applies `edit` to it as one `didChange`. Returns the entries the edit
/// queued, read before they settle, and the work of the edit once settled.
fn reach(
    dir: &TempDir,
    name: &str,
    edit: impl FnOnce(&str) -> String,
) -> (BTreeSet<PathBuf>, Work) {
    let mut documents = Documents::new();
    documents.survey(CheckScope::Workspace, Some(dir.root()));
    let mut index = SymbolIndex::build(&documents, CheckScope::Workspace, Some(dir.root()));
    index.settle(&documents);

    let path = dir.at(&class(name));
    let uri = uri_of(&path).expect("a temp path is UTF-8");
    let text = fs::read_to_string(&path).expect("a library file");
    documents.open(uri.clone(), 1, text.clone());
    documents.resurvey(&path);
    index.refresh(&documents, &path);
    index.settle(&documents);
    assert!(
        index.pending().is_empty(),
        "opening the file queued nothing"
    );
    index.take_work();

    let changed = edit(&text);
    assert_ne!(changed, text, "the edit changed the file");
    assert!(documents.change(&uri, 2, changed), "the document is open");
    documents.resurvey(&path);
    index.refresh(&documents, &path);
    let queued = index.pending().clone();
    index.settle(&documents);
    (queued, index.take_work())
}

/// Replaces the one `from` in `text` with `to`.
fn replace(text: &str, from: &str, to: &str) -> String {
    assert!(text.contains(from), "the file has {from:?}");
    text.replacen(from, to, 1)
}

/// Asserts that an edit queued exactly `expected` and checked `checked` files.
fn assert_reached(
    queued: &BTreeSet<PathBuf>,
    work: Work,
    expected: &BTreeSet<PathBuf>,
    checked: usize,
) {
    assert_eq!(
        queued,
        expected,
        "the edit queued {} entries, not {}",
        queued.len(),
        expected.len()
    );
    assert_eq!(
        work.checked, checked,
        "the edit checked {} files' bodies, not {checked}",
        work.checked
    );
}

/// The generator writes the library and every program, and every file checks
/// clean, so each count below is about the reach and never about an error.
#[test]
fn the_generated_tree_has_the_library_and_the_programs() {
    let dir = tree("generated");
    let mut documents = Documents::new();
    documents.survey(CheckScope::Workspace, Some(dir.root()));
    let mut index = SymbolIndex::build(&documents, CheckScope::Workspace, Some(dir.root()));
    index.settle(&documents);
    assert_eq!(
        index.len(),
        LIBRARY.len() + PROGRAMS,
        "the index holds every file of the tree"
    );
    let mut errors = Vec::new();
    let files = LIBRARY
        .iter()
        .map(|(name, _)| class(name))
        .chain((0..ROLES).map(program));
    for relative in files {
        let path = dir.at(&relative);
        let uri = uri_of(&path).expect("a temp path is UTF-8");
        let text = fs::read_to_string(&path).expect("a generated file");
        documents.open(uri.clone(), 1, text);
        let analysed = nvs_lsp::analyse(&documents, &uri).expect("an open document");
        errors.extend(
            analysed
                .diags
                .iter()
                .filter(|diag| diag.severity == nvs_diagnostics::Severity::Error)
                .map(|diag| format!("{relative}: {:?} {}", diag.code, diag.message)),
        );
    }
    assert!(
        errors.is_empty(),
        "a generated file has an error: {errors:#?}"
    );
    assert_eq!(
        index.files_with_errors(),
        0,
        "a generated file has an error"
    );
    for role in 0..ROLES {
        assert_eq!(
            programs(&dir, &[role]).len(),
            PROGRAMS / ROLES,
            "role {role} has its share of the programs"
        );
    }
}

/// A private method of a class with no subclass is seen by no other file.
/// The many programs that call the class's public method keep their output.
#[test]
fn a_private_member_edit_reaches_no_other_file() {
    let dir = tree("private");
    let (queued, work) = reach(&dir, "Lone", |text| {
        replace(text, "hidden(): int", "hidden(int $by = 0): int")
    });
    assert_reached(&queued, work, &BTreeSet::new(), 1);
}

/// A method added to a class that has no subclass, under a name no file looked
/// for, reaches no other file.
#[test]
fn a_new_member_nobody_names_reaches_no_other_file() {
    let dir = tree("new-unnamed");
    let (queued, work) = reach(&dir, "Lone", |text| {
        replace(
            text,
            "class Lone\n{\n",
            "class Lone\n{\n    public function extra(): int\n    {\n        return 5;\n    }\n\n",
        )
    });
    assert_reached(&queued, work, &BTreeSet::new(), 1);
}

/// A method added under the name a program failed to find on the class
/// reaches that program, and no other reader of the class.
#[test]
fn a_new_member_reaches_the_file_that_failed_to_find_it() {
    let dir = tree("new-missed");
    let missing = program(PROGRAMS);
    dir.write(
        &missing,
        &program_text(
            "use Framework\\Lone;\n\nLone $lone = new Lone();\necho $lone->later(), \"\\n\";\n",
        ),
    );
    let (queued, work) = reach(&dir, "Lone", |text| {
        replace(
            text,
            "class Lone\n{\n",
            "class Lone\n{\n    public function later(): int\n    {\n        return 6;\n    }\n\n",
        )
    });
    let expected = BTreeSet::from([key(&dir, &missing)]);
    assert_reached(&queued, work, &expected, 2);
}

/// A method added to `Base` under the name its subclass `Page` declares
/// reaches the files that declare a subclass, `Page` and `Post`. The programs
/// that call `Page::size` found it on `Page`, so the new method moves nothing
/// they used.
#[test]
fn a_new_member_reaches_the_subclass_that_declares_its_name() {
    let dir = tree("new-subclass");
    let (queued, work) = reach(&dir, "Base", |text| {
        replace(
            text,
            "class Base\n{\n",
            "class Base\n{\n    public function size(): int\n    {\n        return 0;\n    }\n\n",
        )
    });
    assert_reached(&queued, work, &library(&dir, &["Page", "Post"]), 3);
}

/// A method added to an interface reaches every class that implements it,
/// and none of the programs that call the interface's other method.
#[test]
fn a_new_abstract_or_interface_method_reaches_every_implementer() {
    let dir = tree("new-abstract");
    let (queued, work) = reach(&dir, "Shape", |text| {
        replace(
            text,
            "public function area(): int;\n",
            "public function area(): int;\n\n    public function corners(): int;\n",
        )
    });
    assert_reached(&queued, work, &library(&dir, &["Square", "Triangle"]), 3);
}

/// A protected method's new signature reaches the files that declare a
/// subclass, at any depth, and none of the programs that read `Base`.
#[test]
fn a_protected_member_edit_reaches_only_the_subclasses() {
    let dir = tree("protected");
    let (queued, work) = reach(&dir, "Base", |text| {
        replace(text, "guard(): int", "guard(int $by = 0): int")
    });
    assert_reached(&queued, work, &library(&dir, &["Page", "Post"]), 3);
}

/// A public method's new signature reaches the programs that call it and
/// the subclasses. The programs that read `Base` through `Page` keep their
/// output.
#[test]
fn a_public_member_edit_reaches_only_its_users() {
    let dir = tree("public");
    let (queued, work) = reach(&dir, "Base", |text| {
        replace(text, "greet(): string", "greet(string $to = ''): string")
    });
    let mut expected = programs(&dir, &[GREET]);
    expected.extend(library(&dir, &["Page", "Post"]));
    assert_reached(&queued, work, &expected, 1 + expected.len());
}

/// A private property's new type reaches every program that decodes JSON
/// into the class, because the derived codec reads every property.
#[test]
fn a_private_property_edit_reaches_the_files_that_decode_into_the_class() {
    let dir = tree("private-property");
    let (queued, work) = reach(&dir, "Order", |text| {
        replace(text, "private int $total;", "private ?int $total;")
    });
    let expected = programs(&dir, &[DECODE]);
    assert_reached(&queued, work, &expected, 1 + expected.len());
}

/// A new doc comment on an interface reaches every program that used it or
/// one of its methods, and every class that implements it.
#[test]
fn a_class_header_edit_reaches_every_user_of_the_class() {
    let dir = tree("header");
    let (queued, work) = reach(&dir, "Shape", |text| {
        replace(
            text,
            "interface Shape\n",
            "/// Something with an area.\ninterface Shape\n",
        )
    });
    let mut expected = programs(&dir, &[SHAPE]);
    expected.extend(library(&dir, &["Square", "Triangle"]));
    assert_reached(&queued, work, &expected, 1 + expected.len());
}

/// A removed method reaches the programs that called it, which now fail to
/// find it. The other readers of the class keep their output.
#[test]
fn a_removed_member_reaches_its_users() {
    let dir = tree("removed");
    let (queued, work) = reach(&dir, "Lone", |text| {
        replace(
            text,
            "\n\n    public function twice(): int\n    {\n        return 4;\n    }",
            "",
        )
    });
    let expected = programs(&dir, &[TWICE]);
    assert_reached(&queued, work, &expected, 1 + expected.len());
}

/// A new `use` line queues every entry whose graph read the file. Each of
/// them is analysed again, and no name any of them used moved, so the edited
/// file is the only one checked.
#[test]
fn a_graph_edit_reaches_every_reader() {
    let dir = tree("graph");
    let (queued, work) = reach(&dir, "Lone", |text| {
        replace(
            text,
            "namespace Framework;\n",
            "namespace Framework;\n\nuse Framework\\Order;\n",
        )
    });
    let readers: Vec<usize> = (TWICE..ROLES).collect();
    assert_reached(&queued, work, &programs(&dir, &readers), 1);
}
